def _save_hormone_emotion_log(self, emotion, intensity, user_name):
        try:
            import json as _json
            log_path = os.path.join(
                os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__)))),
                'data', 'stream', 'hormone_emotion_log.json'
            )
            log_dir = os.path.dirname(log_path)
            if log_dir:
                os.makedirs(log_dir, exist_ok=True)
            try:
                intensity_value = round(float(intensity), 2)
            except (TypeError, ValueError):
                intensity_value = 0.0
            entry = {
                "timestamp": time.time(),
                "emotion": str(emotion),
                "intensity": intensity_value,
                "user_name": str(user_name),
                "trend": self.get_emotion_trend().get("direction", "stable"),
            }
            with self._emotion_log_lock:
                log_data = []
                if os.path.exists(log_path):
                    try:
                        log_data = safe_read_json(log_path, default=[])
                    except Exception:
                        log_data = []
                if not isinstance(log_data, list):
                    log_data = []
                log_data.append(entry)
                if len(log_data) > 50:
                    log_data = log_data[-50:]
                tmp_path = log_path + '.tmp.' + str(os.getpid())
                try:
                    with open(tmp_path, 'w', encoding='utf-8') as f:
                        _json.dump(log_data, f, ensure_ascii=False)
                        f.flush()
                        os.fsync(f.fileno())
                    os.replace(tmp_path, log_path)
                except Exception:
                    try:
                        if os.path.exists(tmp_path):
                            os.remove(tmp_path)
                    except Exception:
                        pass
                    raise
        except Exception as e:
            self._log(LogLevel.DEBUG, f"data processing exception ignored: {type(e).__name__}: {e}")

