def _get_background_tempo_via_bus(self):
        # 统一入口：优先走脉冲总线 / 注入的 provider，不再直接调用跨模块单例
        # 返回值 1.0 表示不调整周期
        _default = 1.0

        _provider = getattr(self, "_tempo_provider", None)
        if callable(_provider):
            try:
                _value = _provider("background")
                if isinstance(_value, (int, float)) and not isinstance(_value, bool):
                    return float(_value)
            except Exception as e:
                self._log(LogLevel.WARNING, f"tempo provider failed: {type(e).__name__}: {e}")
                return _default

        _bus = getattr(self, "_pulse_bus", None)
        if _bus is None and self.info_field is not None:
            _bus = getattr(self.info_field, "pulse_bus", None)
        if _bus is None and self.info_field is not None:
            _bus = getattr(self.info_field, "_pulse_bus", None)
        if _bus is None:
            self._log(LogLevel.WARNING, "tempo unavailable: pulse bus not configured, using default tempo")
            return _default

        try:
            if hasattr(_bus, "get_tempo_state"):
                _state = _bus.get_tempo_state("background")
                if isinstance(_state, bool):
                    return _default
                if isinstance(_state, (int, float)):
                    return float(_state)
                if isinstance(_state, dict):
                    _tempo = _state.get("tempo")
                    if isinstance(_tempo, (int, float)) and not isinstance(_tempo, bool):
                        return float(_tempo)
            if hasattr(_bus, "query"):
                _state = _bus.query("tempo.background")
                if isinstance(_state, dict):
                    _tempo = _state.get("tempo")
                    if isinstance(_tempo, (int, float)) and not isinstance(_tempo, bool):
                        return float(_tempo)
        except Exception as e:
            self._log(LogLevel.WARNING, f"tempo query failed: {type(e).__name__}: {e}")

        return _default

def _schedule_next_exploration(self):
        # Reentry guard: skip if the previous schedule cycle is still running.
        if not self._running:
            return
        if getattr(self, "_schedule_in_progress", False):
            self._log(LogLevel.DEBUG, "schedule reentry skipped: previous cycle still in progress")
            return
        self._schedule_in_progress = True
        try:
            if self._next_timer:
                self._next_timer.cancel()
            # runtime_tempo external adjustment: speed up when idle, slow down in conversation.
            # Do not mutate _current_interval (internal adaptive logic stays intact);
            # apply tempo only at scheduling time.
            _actual_interval = self._current_interval
            try:
                _tempo = get_runtime_tempo().get_background_tempo()
                _actual_interval = max(self._min_interval, self._current_interval * _tempo)
            except Exception as e:
                self._log(LogLevel.WARNING, f"异常已忽略（需关注）: {type(e).__name__}: {e}")
            self._next_timer = threading.Timer(
                _actual_interval,
                self._trigger_exploration
            )
            self._next_timer.daemon = True
            self._next_timer.start()
        finally:
            self._schedule_in_progress = False

