            for getter_name in ('get_last_signal', 'get_snapshot', 'peek', 'get'):
                getter = getattr(bus, getter_name, None)
                if not callable(getter):
                    continue
                try:
                    snapshot = getter('emotion_trend')
                except Exception:
                    continue
                if isinstance(snapshot, dict):
                    direction = snapshot.get('direction')
                elif isinstance(snapshot, str):
                    direction = snapshot
                if isinstance(direction, str) and direction:
                    break
                direction = None
        if not isinstance(direction, str) or not direction:
            cached = getattr(self, '_last_emotion_trend_direction', None)
            if isinstance(cached, str) and cached:
                direction = cached
        if not isinstance(direction, str) or not direction:
            direction = default
        return direction

def _handle_survival_low(self, snapshot):
        self._survival_state = "low"
        _idx = getattr(snapshot, "index", 30)
        _level = getattr(snapshot, "level", "low")
        self._log(LogLevel.INFO,
                  f"[R4生命层] 存续低位，指数={_idx}，"
                  f"R2自我保存由心跳闭环独立维护")
        # 生命姿态补强: 威胁感知 -> 防御动作即时闭环 (复用 R2 双重防抖, 冷却+防重入零冲突)
        try:
            self._maybe_trigger_self_preservation(
                {"level": _level, "index": _idx, "mode_switched": True})
        except Exception as e:
            self._log(LogLevel.WARNING, f"异常已忽略（需关注）: {type(e).__name__}: {e}")
        # 生命姿态补强: 姿态变化洞察 (供叙事/对话层感知"处于生存紧张状态")
        # 改动点: 不再直接调用 get_insight_board().post(...), 统一经脉冲总线发布, 消除跨模块单例隐式耦合
        try:
            self._publish_insight(
                insight_type="life_posture",
                content=f"生命姿态切换为「存续低位·自我保存」：指数={_idx}",
                source_loop="生命姿态",
                related_dimension="自我存续",
                confidence=_evidence_conf(0.9, "survival", [_idx]),
                keywords=["生命姿态", "存续低位", "自我保存"],
            )
        except Exception as e:
            self._log(LogLevel.WARNING, f"异常已忽略（需关注）: {type(e).__name__}: {e}")
        return {"layer": "life", "state": "low"}

def _publish_insight(self, **payload):
        # 改动点: 新增总线桥接, 仅此处解析发布通道, 上层不再感知 InsightBoard 单例
        bus = None
        for attr in ("_pulse_bus", "pulse_bus", "_bus", "bus", "_pulse"):
            bus = getattr(self, attr, None)
            if bus is not None:
                break
        if bus is None:
            try:
                from nucleus.PulseBus import get_pulse_bus  # 按项目实际脉冲总线模块调整
                bus = get_pulse_bus()
            except Exception:
                bus = None
        if bus is None:
            self._log(LogLevel.WARNING, "脉冲总线不可用, 洞察事件已丢弃: life_posture")
            return False
        emit = None
        for name in ("emit", "publish", "post_insight"):
            candidate = getattr(bus, name, None)
            if callable(candidate):
                emit = candidate
                break
        if emit is None:
            self._log(LogLevel.WARNING, "脉冲总线无可用发布接口, 洞察事件已丢弃: life_posture")
            return False
        emit("insight.post", payload)
        return True

