        # Key change: publish through the pulse bus first, never call the
        # InsightBoard singleton directly on the happy path.
        _payload = {
            "insight_type": "life_posture",
            "content": f"生命姿态恢复「存续高位·舒展」：指数={_idx}",
            "source_loop": "生命姿态",
            "related_dimension": "自我存续",
            "confidence": _evidence_conf(0.9, "survival", [_idx]),
            "keywords": ["生命姿态", "存续高位", "恢复"],
        }
        _bus = None
        try:
            from nucleus.pulse_bus import (  # type: ignore[possibly-unbound]
                get_pulse_bus,
            )
            _bus = get_pulse_bus()
        except Exception as e:
            self._log(LogLevel.WARNING,
                      f"脉冲总线不可用，将走兼容回退: {type(e).__name__}: {e}")
        _published = False
        if _bus is not None:
            try:
                _publish = getattr(_bus, "publish", None)
                if not callable(_publish):
                    _publish = getattr(_bus, "emit", None)
                if callable(_publish):
                    _publish("insight.life_posture", _payload)
                    _published = True
                else:
                    self._log(LogLevel.WARNING,
                              "脉冲总线缺少 publish/emit 接口，将走兼容回退")
            except Exception as e:
                self._log(LogLevel.WARNING,
                          f"脉冲总线发布失败，将走兼容回退: {type(e).__name__}: {e}")
        if not _published:
            # Compat fallback: lazy import, guarded call, no module-level binding.
            try:
                from nucleus.InsightBoard import (
                    get_insight_board,  # type: ignore[possibly-unbound]
                )
                _board = get_insight_board()
                _post = getattr(_board, "post", None)
                if callable(_post):
                    _post(**_payload)
                else:
                    self._log(LogLevel.WARNING, "InsightBoard 缺少 post 接口")
            except Exception as e:
                self._log(LogLevel.WARNING, f"异常已忽略（需关注）: {type(e).__name__}: {e}")
        return {"layer": "life", "state": "high"}

